#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<std::vector<int>> resultGrid(std::vector<std::vector<int>>& image, int threshold) {
        int m = image.size(), n = image[0].size();
        std::vector<std::vector<int>> val(m, std::vector<int>(n, 0));
        std::vector<std::vector<int>> cnt(m, std::vector<int>(n, 0));

        for (int i = 0; i < m - 2; ++i) {
            for (int j = 0; j < n - 2; ++j) {
                bool ok = true;
                int s = 0;
                for (int r = i; r < i + 3; ++r) {
                    for (int c = j; c < j + 3; ++c) {
                        s += image[r][c];
                        if (r + 1 < i + 3 && std::abs(image[r][c] - image[r + 1][c]) > threshold) ok = false;
                        if (c + 1 < j + 3 && std::abs(image[r][c] - image[r][c + 1]) > threshold) ok = false;
                    }
                }
                if (ok) {
                    int avg = s / 9;
                    for (int r = i; r < i + 3; ++r) {
                        for (int c = j; c < j + 3; ++c) {
                            val[r][c] += avg;
                            cnt[r][c]++;
                        }
                    }
                }
            }
        }
        std::vector<std::vector<int>> ans(m, std::vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                ans[i][j] = cnt[i][j] > 0 ? val[i][j] / cnt[i][j] : image[i][j];
            }
        }
        return ans;
    }
};

