    const val = Array.from({ length: m }, () => new Array(n).fill(0));
    const cnt = Array.from({ length: m }, () => new Array(n).fill(0));

    for (let i = 0; i < m - 2; ++i) {
        for (let j = 0; j < n - 2; ++j) {
            let ok = true;
            let s = 0;
            for (let r = i; r < i + 3; ++r) {
                for (let c = j; c < j + 3; ++c) {
                    s += image[r][c];
                    if (r + 1 < i + 3 && Math.abs(image[r][c] - image[r + 1][c]) > threshold) ok = false;
                    if (c + 1 < j + 3 && Math.abs(image[r][c] - image[r][c + 1]) > threshold) ok = false;
                }
